/**
 * Shape of `catalog.json`: the Postgres schema the store emulates, reduced to what it needs.
 * Generated by `scripts/firestore/dump-catalog.ts`.
 */

/** How a column's value is stored in Firestore and handed to query code. See docs/firestore/design.md. */
export type ColumnKind =
  /** uuid, text, varchar, enum, inet */
  | 'string'
  /** numeric: an exact decimal string, as `pg` returns it */
  | 'decimal'
  /** bigint: a decimal string, as `pg` returns it */
  | 'int8'
  /** integer, smallint */
  | 'int'
  /** real, double precision */
  | 'float'
  | 'bool'
  /** `YYYY-MM-DD` string (the server's pg type parsers keep dates as strings) */
  | 'date'
  /** `HH:MM:SS` string */
  | 'time'
  /** timestamp / timestamptz: a `Date` in rows, a Firestore Timestamp at rest */
  | 'timestamp'
  /** json / jsonb: the parsed value in rows, JSON text at rest */
  | 'json'
  /** bit(n): a string of 0 and 1 */
  | 'bits';

export type ColumnDefault =
  | { kind: 'uuidv7' }
  | { kind: 'uuid4' }
  /** transaction start time (`now()`, `CURRENT_TIMESTAMP`) */
  | { kind: 'now' }
  /** wall-clock time (`clock_timestamp()`) */
  | { kind: 'clock' }
  | { kind: 'today' }
  | { kind: 'literal'; value: unknown };

export interface ColumnMeta {
  name: string;
  /** Postgres type as written in the schema, without the `accounter_schema.` prefix */
  pgType: string;
  kind: ColumnKind;
  array: boolean;
  notNull: boolean;
  default: ColumnDefault | null;
}

export interface UniqueMeta {
  name: string;
  columns: string[];
  nullsNotDistinct: boolean;
  /** Expression or partial unique index, enforced by a hand-written check in constraints.ts. */
  custom: boolean;
  definition?: string;
}

export interface ForeignKeyMeta {
  name: string;
  columns: string[];
  refTable: string;
  refColumns: string[];
  onDelete: 'noaction' | 'restrict' | 'cascade' | 'setnull' | 'setdefault';
}

export interface TableMeta {
  name: string;
  /**
   * `owner`: rows live under `tenants/{ownerColumn}/{table}`; reads see the request's business scope,
   * writes only the current business. `global`: rows live in a top-level collection.
   */
  tenancy: 'owner' | 'global';
  ownerColumn: string | null;
  /**
   * For global tables with RLS: `readonly` (the app may not write them), or the column a write must
   * set to the current business id.
   */
  writeGuard: null | 'readonly' | string;
  /**
   * Which rows a request reads. `scope`: every business in the request's business scope. `current`:
   * only the current business. `all`: every row (global tables). A global table with a guard column
   * that is not readable by all (`email_ingestion_quarantine`) reads `current` on that column.
   */
  readScope: 'scope' | 'current' | 'all';
  /** null for the few tables without a primary key; their documents get a hidden id. */
  primaryKey: string[] | null;
  columns: ColumnMeta[];
  uniques: UniqueMeta[];
  foreignKeys: ForeignKeyMeta[];
  checks: { name: string; definition: string }[];
}

export interface CatalogFile {
  /** Name of the newest migration the catalog was built from. */
  schemaVersion: string;
  enums: Record<string, string[]>;
  tables: TableMeta[];
}
